set -eu
cd "$HOME/native-managed-broker-effects-3b-v1"
python3 - <<'PY'
import base64,pathlib,hashlib,json
root=pathlib.Path('source')
files={"crates/shards/tests/managed_output/broker_effects.rs":"","docs/research/measurements/managed-broker-effects/register.patch":"","docs/research/measurements/managed-broker-effects/caller.py":""}
for p,b in files.items():
 q=root/p
 q.parent.mkdir(parents=True,exist_ok=True)
 assert not q.exists(),p
 q.write_bytes(base64.b64decode(b))
 print(p,hashlib.sha256(q.read_bytes()).hexdigest())
PY
cd source
git apply docs/research/measurements/managed-broker-effects/register.patch
git diff --check
mkdir -p ../cargo-home
export CARGO_HOME="$HOME/native-managed-broker-effects-3b-v1/cargo-home"
export CARGO_TARGET_DIR="$HOME/native-managed-broker-effects-3b-v1/target"
export CARGO_BUILD_JOBS=2
export CARGO_INCREMENTAL=0
export CC_x86_64_unknown_linux_musl="$PWD/scripts/zig-cc"
export AR_x86_64_unknown_linux_musl="$PWD/scripts/zig-ar"
export ZIG_TARGET=x86_64-linux-musl
unset DYLD_LIBRARY_PATH DYLD_FALLBACK_LIBRARY_PATH SHARDS_HELPERS SHARDS_HELPERS_DIR SHARDS_INIT_BINARY SHARDS_SERVER_BINARY
rustc --version > ../evidence/toolchain.txt
zig version >> ../evidence/toolchain.txt
uname -a >> ../evidence/toolchain.txt
git rev-parse HEAD >> ../evidence/toolchain.txt
set +e
timeout --signal=TERM --kill-after=15s 3600s cargo test --locked -p shards --profile test-release --test managed_output --no-run -j2 > ../evidence/test-build.log 2>&1
rc=$?
printf '%s\n' "$rc" > ../evidence/test-build.exit
 tail -60 ../evidence/test-build.log
exit "$rc"
